CREATE TABLE IF NOT EXISTS project      (id TEXT PRIMARY KEY, name TEXT NOT NULL UNIQUE, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS dataset      (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), name TEXT NOT NULL, description TEXT, purpose TEXT NOT NULL DEFAULT 'eval' CHECK (purpose IN ('eval','judge_labels')), created_at TEXT NOT NULL, UNIQUE(project_id, name));
CREATE TABLE IF NOT EXISTS dataset_item (id TEXT PRIMARY KEY, dataset_id TEXT NOT NULL REFERENCES dataset(id), input TEXT NOT NULL, expected TEXT, metadata TEXT, tags TEXT, source_trace_id TEXT, archived_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS run          (id TEXT PRIMARY KEY, dataset_id TEXT NOT NULL REFERENCES dataset(id), name TEXT NOT NULL, metadata TEXT, item_count INTEGER, items_hash TEXT, started_at TEXT NOT NULL, ended_at TEXT);
CREATE TABLE IF NOT EXISTS trace        (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), run_id TEXT REFERENCES run(id), dataset_item_id TEXT REFERENCES dataset_item(id), input TEXT, output TEXT, expected TEXT, metadata TEXT, tags TEXT, start TEXT NOT NULL, "end" TEXT, metrics TEXT, messages TEXT, events TEXT, spans TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS judge        (name TEXT PRIMARY KEY, active_version_id TEXT REFERENCES judge_version(id), description TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS judge_version (id TEXT PRIMARY KEY, judge_name TEXT NOT NULL REFERENCES judge(name), number INTEGER NOT NULL, parent_id TEXT REFERENCES judge_version(id), scope TEXT NOT NULL DEFAULT 'transcript' CHECK (scope IN ('turn','transcript')), prompt TEXT NOT NULL, model TEXT NOT NULL, params TEXT, examples TEXT, content_hash TEXT NOT NULL, created_by TEXT NOT NULL CHECK (created_by IN ('human','agent')), note TEXT, created_at TEXT NOT NULL, UNIQUE (judge_name, number), UNIQUE (judge_name, content_hash));
CREATE TABLE IF NOT EXISTS score        (id TEXT PRIMARY KEY, trace_id TEXT NOT NULL REFERENCES trace(id), name TEXT NOT NULL, turn INTEGER, value REAL NOT NULL, label TEXT, reason TEXT, source TEXT NOT NULL CHECK (source IN ('sdk','judge','human')), judge_version_id TEXT REFERENCES judge_version(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS judge_calibration (judge_version_id TEXT NOT NULL REFERENCES judge_version(id), dataset_id TEXT REFERENCES dataset(id), split TEXT NOT NULL CHECK (split IN ('dev','test')), n INTEGER NOT NULL, tpr REAL NOT NULL, tnr REAL NOT NULL, created_at TEXT NOT NULL, PRIMARY KEY (judge_version_id, split));
CREATE TABLE IF NOT EXISTS attribute_map (project_id TEXT NOT NULL REFERENCES project(id), source TEXT NOT NULL, target TEXT NOT NULL, type TEXT NOT NULL CHECK (type IN ('string','number','boolean')), PRIMARY KEY (project_id, source));
CREATE TABLE IF NOT EXISTS alert_rule   (id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES project(id), name TEXT NOT NULL, enabled INTEGER NOT NULL DEFAULT 1, trigger TEXT NOT NULL, condition TEXT NOT NULL, channel TEXT NOT NULL, cooldown_s INTEGER NOT NULL DEFAULT 3600, last_fired_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alert_delivery (id TEXT PRIMARY KEY, rule_id TEXT NOT NULL REFERENCES alert_rule(id), payload TEXT NOT NULL, status TEXT NOT NULL, response TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS trace_run ON trace(run_id);
CREATE INDEX IF NOT EXISTS trace_item ON trace(dataset_item_id);
CREATE INDEX IF NOT EXISTS score_trace ON score(trace_id, name, turn);
CREATE INDEX IF NOT EXISTS item_source ON dataset_item(source_trace_id);
